#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    int edges = n * (n - 1) / 2;
    vector<vector<vector<int>>> dp_table(n + 1, vector<vector<int>>(edges + 1, vector<int>(n + 1, 0)));
    dp_table[1][0][1] = 1;

    for (int i = 1; i < n; ++i) {
        for (int j = 0; j <= edges; ++j) {
            for (int k = 1; k <= n; ++k) {
                int val = dp_table[i][j][k];
                if (val == 0) continue;
                if (j + i <= edges) {
                    dp_table[i + 1][j + i][i + 1] = (dp_table[i + 1][j + i][i + 1] + val) % m;
                }
                for (int l = 0; l < i; ++l) {
                    int nj = j + i - 1 - l;
                    if (nj <= edges) {
                        dp_table[i + 1][nj][k] = (dp_table[i + 1][nj][k] + val) % m;
                    }
                }
            }
        }
    }

    vector<vector<vector<int>>> prefix_sum_dp(n + 1, vector<vector<int>>(n + 1, vector<int>(edges + 1, 0)));
    for (int i = 0; i <= n; ++i) {
        for (int k = 1; k <= n; ++k) {
            int total = 0;
            for (int j = 0; j <= edges; ++j) {
                total = (total + dp_table[i][j][k]) % m;
                prefix_sum_dp[i][k][j] = total;
            }
        }
    }

    vector<vector<vector<int>>> cumulative_sum(n + 1, vector<vector<int>>(edges + 1, vector<int>(n + 1, 0)));
    for (int i = 0; i <= n; ++i) {
        for (int j = 0; j <= edges; ++j) {
            int total = 0;
            for (int k = 1; k <= n; ++k) {
                total = (total + prefix_sum_dp[i][k][j]) % m;
                cumulative_sum[i][j][k] = total;
            }
        }
    }

    vector<long long> result(n + 1, 0);
    for (int i = 1; i <= n; ++i) {
        long long res = (long long)i * result[i - 1] % m;
        for (int k = 1; k <= n; ++k) {
            for (int j = 1; j <= edges; ++j) {
                if (dp_table[i][j][k] == 0) continue;
                long long delta = (long long)dp_table[i][j][k] * (cumulative_sum[i][j - 1][n] - cumulative_sum[i][j - 1][k]);
                delta %= m;
                res = (res + delta + m) % m;
            }
        }
        result[i] = res;
    }

    cout << result[n] << "\n";

    return 0;
}
